PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry layernorm_fp16(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 N
)
{
    // --------------------
    // registers
    // --------------------
    .reg .pred  %p<4>;
    .reg .b32   %r<15>;
    .reg .b64   %rd<12>;
    .reg .f32   %f<12>;
    .reg .b16   %h<2>;

    // --------------------
    // load kernel params
    // --------------------
    ld.param.u64    %rd1, [in_ptr];
    ld.param.u64    %rd2, [out_ptr];
    ld.param.u32    %r1,  [N];          // total elements per batch

    // thread / block indices
    mov.u32 %r2, %ctaid.x;            // batch index
    mov.u32 %r3, %ntid.x;             // blockDim.x
    mov.u32 %r4, %tid.x;              // threadIdx.x

    // --------------------
    // compute base address for this batch
    // --------------------
    cvt.u64.u32   %rd3, %r2;          // batch as 64‑bit
    mul.lo.u64    %rd3, %rd3, %r1;    // batch * N
    mul.lo.u64    %rd3, %rd3, 2;      // *sizeof(half)
    add.u64       %rd4, %rd1, %rd3;   // in_ptr + offset
    add.u64       %rd5, %rd2, %rd3;   // out_ptr + offset

    // --------------------
    // shared memory for reductions (256 * 4 bytes)
    // --------------------
    .shared .align 4 .b8 sdata[1024];

    // -------------------------------------------------
    // 1) compute mean  (partial sum per thread -> reduce)
    // -------------------------------------------------
    mov.f32 %f0, 0f0;                 // thread partial sum
    mov.u32 %r6, %r4;                 // i = threadIdx
SUM_LOOP:
    setp.ge.u32 %p0, %r6, %r1;
    @%p0 bra SUM_DONE;
    mul.lo.u64 %rd6, %r6, 2;          // byte offset
    add.u64 %rd7, %rd4, %rd6;
    ld.global.u16 %h0, [%rd7];
    cvt.f32.f16 %f1, %h0;
    add.f32 %f0, %f0, %f1;
    add.u32 %r6, %r6, %r3;            // i += blockDim
    bra SUM_LOOP;
SUM_DONE:

    // store partial sum to shared (byte offset = tid*4)
    mul.lo.u32 %r7, %r4, 4;
    cvt.u64.u32 %rd8, %r7;
    st.shared.f32 [sdata+%rd8], %f0;
    bar.sync 0;

    // reduction in shared memory
REDUCTION_MEAN:
    shr.u32 %r8, %r3, 1;              // stride = blockDim/2
    setp.lt.u32 %p1, %r4, %r8;
    @!%p1 bra REDUCTION_MEAN_END;
    // load a = sdata[tid]
    mul.lo.u32 %r9, %r4, 4;
    cvt.u64.u32 %rd9, %r9;
    ld.shared.f32 %f2, [sdata+%rd9];
    // load b = sdata[tid + stride]
    add.u32 %r10, %r4, %r8;
    mul.lo.u32 %r10, %r10, 4;
    cvt.u64.u32 %rd10, %r10;
    ld.shared.f32 %f3, [sdata+%rd10];
    add.f32 %f2, %f2, %f3;
    st.shared.f32 [sdata+%rd9], %f2;
    bar.sync 0;
    mov.u32 %r3, %r8;                 // blockDim = stride
    bra REDUCTION_MEAN;
REDUCTION_MEAN_END:
    // after reduction, thread 0 holds total sum
    ld.shared.f32 %f4, [sdata];       // total sum
    cvt.f32.u32 %f5, %r1;             // N as float
    div.full.f32 %f6, %f4, %f5;       // mean

    // -------------------------------------------------
    // 2) compute variance (partial sum of (x-mean)^2)
    // -------------------------------------------------
    mov.f32 %f7, 0f0;                 // thread partial var sum
    mov.u32 %r6, %r4;                 // i = threadIdx
VAR_LOOP:
    setp.ge.u32 %p0, %r6, %r1;
    @%p0 bra VAR_DONE;
    mul.lo.u64 %rd6, %r6, 2;
    add.u64 %rd7, %rd4, %rd6;
    ld.global.u16 %h0, [%rd7];
    cvt.f32.f16 %f1, %h0;
    sub.f32 %f1, %f1, %f6;            // (x - mean)
    mul.f32 %f1, %f1, %f1;            // square
    add.f32 %f7, %f7, %f1;
    add.u32 %r6, %r6, %r3;
    bra VAR_LOOP;
VAR_DONE:

    // store partial variance to shared (reuse same buffer)
    mul.lo.u32 %r7, %r4, 4;
    cvt.u64.u32 %rd8, %r7;
    st.shared.f32 [sdata+%rd8], %f7;
    bar.sync 0;

    // reduction for variance
    mov.u32 %r3, %ntid.x;            // reset blockDim to original
REDUCTION_VAR:
    shr.u32 %r8, %r3, 1;              // stride
    setp.lt.u32 %p1, %r4, %r8;
    @!%p1 bra REDUCTION_VAR_END;
    // load a = sdata[tid]
    mul.lo.u32 %r9, %r4, 4;
    cvt.u64.u32 %rd9, %r9;
    ld.shared.f32 %f2, [sdata+%rd9];
    // load b = sdata[tid + stride]
    add.u32 %r10, %r4, %r8;
    mul.lo.u32 %r10, %r10, 4;
    cvt.u64.u32 %rd10, %r10;
    ld.shared.f32 %f3, [sdata+%rd10];
    add.f32 %f2, %f2, %f3;
    st.shared.f32 [sdata+%rd9], %f2;
    bar.sync 0;
    mov.u32 %r3, %r8;
    bra REDUCTION_VAR;
REDUCTION_VAR_END:
    ld.shared.f32 %f8, [sdata];       // total variance sum
    cvt.f32.u32 %f9, %r1;             // N as float
    div.full.f32 %f10, %f8, %f9;      // variance

    // -------------------------------------------------
    // 3) compute inverse stddev (rsqrt(var + eps))
    // -------------------------------------------------
    add.f32 %f10, %f10, 1e-5;         // eps = 1e-5
    rsqrt.approx.f32 %f11, %f10;     // 1/sqrt(var+eps)

    // -------------------------------------------------
    // 4) write normalized output
    // -------------------------------------------------
    mov.u32 %r6, %r4;                 // i = threadIdx
WRITE_LOOP:
    setp.ge.u32 %p0, %r6, %r1;
    @%p0 bra WRITE_DONE;
    mul.lo.u64 %rd6, %r6, 2;
    add.u64 %rd7, %rd4, %rd6;
    ld.global.u16 %h0, [%rd7];
    cvt.f32.f16 %f1, %h0;
    sub.f32 %f1, %f1, %f6;            // (x - mean)
    mul.f32 %f1, %f1, %f11;           // * inv_std
    cvt.f16.f32 %h0, %f1;             // back to half
    mul.lo.u64 %rd6, %r6, 2;
    add.u64 %rd7, %rd5, %rd6;
    st.global.u16 [%rd7], %h0;
    add.u32 %r6, %r6, %r3;
    bra WRITE_LOOP;
WRITE_DONE:
    ret;
}
'''

class ModelNew:
    def __init__(self):
        # load PTX module
        self.module = ptx_load(PTX_SOURCE)
        self.kernel_name = "layernorm_fp16"

    def __call__(self, x):
        # x: torch.Tensor of dtype torch.float16, shape (B, C, H, W)
        assert x.dtype == torch.float16
        batch = x.shape[0]
        N = x.numel() // batch          # elements per batch (C*H*W)
        out = torch.empty_like(x)

        # launch configuration
        grid  = (batch,)
        block = (256,)          # 256 threads per block

        # arguments must be passed as a list of 64‑bit values
        args = [x.data_ptr(), out.data_ptr(), int(N)]

        ptx_launch(self.module, self.kernel_name, grid, block, args)
        return out
